1	//! GLM5.2's [`ModelLine`] implementation: topology-aware validation, the
2	//! GLM5.2-exclusive CLI section, the frontend serve plan (partition count,
3	//! prefill-only), and launch-option assembly.
4	
5	use std::collections::BTreeSet;
6	
7	use clap::Args as ClapArgs;
8	use clap::FromArgMatches;
9	use pegainfer_frontend::engine::LaunchedEngine;
10	use pegainfer_frontend::model_line::CliError;
11	use pegainfer_frontend::model_line::LaunchContext;
12	use pegainfer_frontend::model_line::ModelLine;
13	use pegainfer_frontend::model_line::ServePlan;
14	
15	use crate::Glm52Drafter;
16	use crate::Glm52KvOffloadOptions;
17	use crate::Glm52LaunchOptions;
18	use crate::Glm52MoeTopo;
19	use crate::Glm52P2pOptions;
20	use crate::Glm52PrefillOnlyOptions;
21	
22	pub static MODEL_LINE: Glm52Line = Glm52Line;
23	
24	pub struct Glm52Line;
25	
26	// GLM5.2-exclusive CLI flags.
27	#[derive(ClapArgs)]
28	struct Glm52Cli {
29	    /// Per-request context cap: prompt + max_tokens - 1 must fit. When
30	    /// omitted, GLM5.2 sizes it from post-weight-load free VRAM.
31	    #[arg(long)]
32	    max_model_len: Option<usize>,
33	
34	    /// Run GLM5.2 TP4 with prefix caching and no decode.
35	    #[arg(long, default_value_t = false)]
36	    glm52_prefill_only: bool,
37	
38	    /// Token rows per prefill chunk. Must be a multiple of 64.
39	    #[arg(long, default_value_t = 16_384)]
40	    glm52_prefill_chunk_size: usize,
41	
42	    /// GLM5.2 launch-time MoE sharding topology: `ep8` (default) is the
43	    /// high-throughput configuration (32 whole experts per rank, DeepEP
44	    /// dispatch/combine, buckets 1-8); `ep4` is its four-GPU counterpart
45	    /// (64 whole experts per rank, weight-only expert GEMMs — the GB300
46	    /// high-throughput topology); `tp4` is GB300 **prefill-only** tensor
47	    /// parallel (requires `--glm52-prefill-only`; NCCL all-reduce). Hopper
48	    /// (SM9x) and decode TP/LL paths are not supported.
49	    #[arg(long, default_value = "ep8")]
50	    moe_topo: String,
51	
52	    /// Use GLM5.2's checkpoint-native MTP layer as the speculative drafter.
53	    #[arg(long = "glm52-native-mtp")]
54	    glm52_native_mtp: bool,
55	
56	    /// Stage GLM5.2 checkpoint bytes through pinned double buffers. This can
57	    /// substantially accelerate warm-page-cache loads; leave off for cold
58	    /// network-filesystem starts.
59	    #[arg(long)]
60	    glm52_weight_staging: bool,
61	
62	    /// GLM5.2 global DP ranks this process hosts, `start..end` (e.g. `4..8`).
63	    /// Default: the whole topology (single-node). A partial range is the
64	    /// multi-process cross-node shape: every node runs the same binary over
65	    /// its own ranks, and requires `--glm52-rendezvous`.
66	    #[arg(long)]
67	    glm52_ranks: Option<String>,
68	
69	    /// GLM5.2 bootstrap rendezvous address (`host:port`): the process hosting
70	    /// rank 0 binds it and serves the DeepEP unique id; every other process
71	    /// connects to fetch it. A one-time handshake — no runtime control plane.
72	    #[arg(long)]
73	    glm52_rendezvous: Option<String>,
74	}
75	
76	fn cli(ctx: &LaunchContext<'_>) -> Glm52Cli {
77	    Glm52Cli::from_arg_matches(ctx.matches).expect("Glm52Cli parses from the merged command")
78	}
79	
80	/// Parse `--moe-topo` with the accepted strings owned by the model crate, so
81	/// an invalid value fails with the real problem instead of a misleading
82	/// dp/tp complaint.
83	fn moe_topo(cli: &Glm52Cli) -> Result<Glm52MoeTopo, CliError> {
84	    cli.moe_topo
85	        .parse()
86	        .map_err(|err| CliError::rule(format!("--moe-topo: {err}")))
87	}
88	
89	impl ModelLine for Glm52Line {
90	    fn name(&self) -> &'static str {
91	        "GLM5.2"
92	    }
93	
94	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
95	        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
96	        if model_type != Some("glm_moe_dsa") {
97	            return Err(format!("model_type {model_type:?} is not \"glm_moe_dsa\""));
98	        }
99	        crate::probe_config_json(config).map_err(|error| error.to_string())
100	    }
101	
102	    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
103	        Glm52Cli::augment_args(cmd)
104	    }
105	
106	    fn consumed_shared_args(&self) -> &'static [&'static str] {
107	        &[
108	            "tp_size",
109	            "dp_size",
110	            "dflash_draft_model_path",
111	            "no_prefix_cache",
112	            "kv_offload",
113	            "kv_offload_host_gib",
114	            "kv_offload_hugepages",
115	            "kv_p2p_metaserver_addr",
116	            "kv_p2p_advertise_addr",
117	            "kv_p2p_nics",
118	            "dump_graph_png",
119	        ]
120	    }
121	
122	    fn validate(
123	        &self,
124	        ctx: &LaunchContext<'_>,
125	        provided: &BTreeSet<String>,
126	    ) -> Result<(), CliError> {
127	        let cli = cli(ctx);
128	        let shared = ctx.shared;
129	        let moe_topo = moe_topo(&cli)?;
130	        if let Some(dp_size) = shared.dp_size {
131	            let expected_dp_size = moe_topo.default_dp_size();
132	            if dp_size != expected_dp_size {
133	                return Err(CliError::rule(format!(
134	                    "GLM5.2 --moe-topo={} requires --dp-size={expected_dp_size} when provided; omit --dp-size to use the topology default",
135	                    cli.moe_topo
136	                )));
137	            }
138	        }
139	        let expected_tp_size = moe_topo.expected_tp_size();
140	        if shared.tp_size != expected_tp_size {
141	            return Err(CliError::rule(format!(
142	                "GLM5.2 --moe-topo={} requires --tp-size={expected_tp_size}, got {}",
143	                cli.moe_topo, shared.tp_size
144	            )));
145	        }
146	        if cli.glm52_prefill_only {
147	            if !matches!(moe_topo, Glm52MoeTopo::Tp4) {
148	                return Err(CliError::rule(
149	                    "--glm52-prefill-only requires --moe-topo=tp4",
150	                ));
151	            }
152	            if shared.no_prefix_cache {
153	                return Err(CliError::rule(
154	                    "--glm52-prefill-only requires prefix caching; drop --no-prefix-cache",
155	                ));
156	            }
157	            if shared.dflash_draft_model_path.is_some() {
158	                return Err(CliError::rule(
159	                    "--glm52-prefill-only is incompatible with the DSpark drafter",
160	                ));
161	            }
162	            if shared.kv_offload && !cli.glm52_native_mtp {
163	                return Err(CliError::rule(
164	                    "--glm52-prefill-only KV offload requires --glm52-native-mtp",
165	                ));
166	            }
167	            if shared.dump_graph_png.is_some() {
168	                return Err(CliError::rule(
169	                    "--glm52-prefill-only does not expose a decode CUDA graph",
170	                ));
171	            }
172	        } else if provided.contains("glm52_prefill_chunk_size") {
173	            return Err(CliError::rule(
174	                "--glm52-prefill-chunk-size requires --glm52-prefill-only",
175	            ));
176	        }
177	        if cli.glm52_prefill_chunk_size == 0
178	            || !cli
179	                .glm52_prefill_chunk_size
180	                .is_multiple_of(crate::GLM52_PREFILL_CHUNK_ALIGN)
181	        {
182	            return Err(CliError::rule(format!(
183	                "--glm52-prefill-chunk-size must be a positive multiple of {}, got {}",
184	                crate::GLM52_PREFILL_CHUNK_ALIGN,
185	                cli.glm52_prefill_chunk_size
186	            )));
187	        }
188	        if cli.glm52_native_mtp && shared.dflash_draft_model_path.is_some() {
189	            return Err(CliError::rule(
190	                "--glm52-native-mtp and --dflash-draft-model-path are mutually exclusive",
191	            ));
192	        }
193	        if cli.glm52_native_mtp
194	            && !matches!(
195	                moe_topo,
196	                Glm52MoeTopo::Ep4
197	                    | Glm52MoeTopo::Ep8
198	                    | Glm52MoeTopo::Ep16
199	                    | Glm52MoeTopo::Ep32
200	                    | Glm52MoeTopo::Ep64
201	            )
202	            && !(cli.glm52_prefill_only && matches!(moe_topo, Glm52MoeTopo::Tp4))
203	        {
204	            return Err(CliError::rule(
205	                "--glm52-native-mtp requires EP decode (--moe-topo=ep4 or ep8 and up) or TP4 prefill-only",
206	            ));
207	        }
208	        Ok(())
209	    }
210	
211	    fn serve_plan(&self, ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
212	        let cli = cli(ctx);
213	        let moe_topo = moe_topo(&cli)?;
214	        let scheduler_partition_count = match &cli.glm52_ranks {
215	            // A partial fleet hosts only its own ranks; a mirrored topology
216	            // always collapses to one logical rank.
217	            Some(spec) if !moe_topo.uses_tensor_replicated_moe() => crate::parse_rank_range(spec)
218	                .map_err(|err| CliError::rule(format!("--glm52-ranks: {err}")))?
219	                .len(),
220	            _ => moe_topo.logical_rank_count(),
221	        };
222	        Ok(ServePlan {
223	            scheduler_partition_count,
224	            prefill_only: cli.glm52_prefill_only,
225	            ..ServePlan::default()
226	        })
227	    }
228	
229	    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
230	        use anyhow::Context;
231	        let cli = cli(ctx);
232	        let shared = ctx.shared;
233	        let moe_topo = moe_topo(&cli)?;
234	        let drafter = if cli.glm52_native_mtp {
235	            Glm52Drafter::NativeMtp
236	        } else if let Some(path) = &shared.dflash_draft_model_path {
237	            Glm52Drafter::Dspark(path.clone())
238	        } else {
239	            Glm52Drafter::None
240	        };
241	        crate::launch(
242	            ctx.model_path,
243	            Glm52LaunchOptions {
244	                tp_size: shared.tp_size,
245	                dp_size: shared.dp_size.unwrap_or_else(|| moe_topo.default_dp_size()),
246	                drafter,
247	                max_model_len: cli.max_model_len,
248	                prefill_only: cli.glm52_prefill_only.then_some(Glm52PrefillOnlyOptions {
249	                    chunk_size: cli.glm52_prefill_chunk_size,
250	                }),
251	                no_prefix_cache: shared.no_prefix_cache,
252	                kv_offload: shared.kv_offload.then(|| Glm52KvOffloadOptions {
253	                    pinned_pool_bytes: (shared.kv_offload_host_gib * f64::from(1u32 << 30))
254	                        as usize,
255	                    use_hugepages: shared.kv_offload_hugepages,
256	                    p2p: match (
257	                        shared.kv_p2p_metaserver_addr.clone(),
258	                        shared.kv_p2p_advertise_addr.clone(),
259	                    ) {
260	                        (Some(metaserver_addr), Some(advertise_addr)) => Some(Glm52P2pOptions {
261	                            metaserver_addr,
262	                            advertise_addr,
263	                            rdma_nics: shared.kv_p2p_nics.clone(),
264	                        }),
265	                        _ => None,
266	                    },
267	                }),
268	                moe_topo,
269	                weight_staging: cli.glm52_weight_staging,
270	                dump_graph_png: shared.dump_graph_png.clone(),
271	                ranks: cli
272	                    .glm52_ranks
273	                    .as_deref()
274	                    .map(crate::parse_rank_range)
275	                    .transpose()
276	                    .context("--glm52-ranks")?,
277	                rendezvous: cli.glm52_rendezvous.clone(),
278	            },
279	        )
280	        .context("failed to start GLM5.2 engine")
281	        .map(LaunchedEngine::Handle)
282	    }
283	}
284	
285	#[cfg(test)]
286	mod tests {
287	    use pegainfer_frontend::model_line::parse_for_line;
288	
289	    use super::*;
290	
291	    fn validate_argv(argv: &[&str]) -> Result<(), CliError> {
292	        let (shared, matches, provided) =
293	            parse_for_line(&MODEL_LINE, argv).map_err(|error| CliError::rule(error.to_string()))?;
294	        let config = serde_json::json!({});
295	        let ctx = LaunchContext {
296	            model_path: std::path::Path::new("unused"),
297	            config: &config,
298	            shared: &shared,
299	            matches: &matches,
300	        };
301	        MODEL_LINE.validate(&ctx, &provided)
302	    }
303	
304	    #[test]
305	    fn accepts_graph_png_dump() {
306	        validate_argv(&["pegainfer", "--dump-graph-png", "decode.png"])
307	            .expect("GLM5.2 should accept a graph PNG dump");
308	    }
309	
310	    #[test]
311	    fn accepts_omitted_dp_size() {
312	        validate_argv(&["pegainfer"])
313	            .expect("GLM5.2 should default to DP8/EP8 when --dp-size is omitted");
314	    }
315	
316	    #[test]
317	    fn accepts_native_mtp_on_ep8() {
318	        validate_argv(&["pegainfer", "--glm52-native-mtp"])
319	            .expect("native MTP should validate on the default EP8 topology");
320	    }
321	
322	    #[test]
323	    fn accepts_native_mtp_on_ep4() {
324	        validate_argv(&["pegainfer", "--glm52-native-mtp", "--moe-topo", "ep4"])
325	            .expect("native MTP should validate on EP4");
326	    }
327	
328	    #[test]
329	    fn native_mtp_rejects_a_second_drafter() {
330	        let error = validate_argv(&[
331	            "pegainfer",
332	            "--glm52-native-mtp",
333	            "--dflash-draft-model-path",
334	            "/tmp/dspark",
335	        ])
336	        .expect_err("native MTP and DSpark must be mutually exclusive");
337	        assert!(error.to_string().contains("mutually exclusive"), "{error}");
338	    }
339	
340	    #[test]
341	    fn native_mtp_rejects_tp_topology() {
342	        let error = validate_argv(&[
343	            "pegainfer",
344	            "--glm52-native-mtp",
345	            "--moe-topo",
346	            "tp4",
347	            "--tp-size",
348	            "4",
349	        ])
350	        .expect_err("native MTP currently requires EP decode");
351	        assert!(
352	            error.to_string().contains("--moe-topo=ep4 or ep8"),
353	            "{error}"
354	        );
355	    }
356	
357	    #[test]
358	    fn rejects_non_dp8_for_ep8() {
359	        let error = validate_argv(&["pegainfer", "--dp-size", "1"])
360	            .expect_err("GLM5.2 should reject explicit non-DP8");
361	        assert!(error.to_string().contains("--dp-size=8"));
362	    }
363	
364	    #[test]
365	    fn accepts_tp4_dp1() {
366	        validate_argv(&["pegainfer", "--moe-topo", "tp4", "--tp-size", "4"])
367	            .expect("GLM5.2 TP4 should default to DP1");
368	    }
369	
370	    #[test]
371	    fn tp4_rejects_non_dp1() {
372	        let error = validate_argv(&[
373	            "pegainfer",
374	            "--moe-topo",
375	            "tp4",
376	            "--tp-size",
377	            "4",
378	            "--dp-size",
379	            "8",
380	        ])
381	        .expect_err("GLM5.2 TP4 should reject explicit non-DP1");
382	        assert!(error.to_string().contains("--dp-size=1"));
383	    }
384	
385	    #[test]
386	    fn tp4_rejects_omitted_tp_size() {
387	        let error = validate_argv(&["pegainfer", "--moe-topo", "tp4"])
388	            .expect_err("GLM5.2 TP4 should reject the default --tp-size=1");
389	        assert!(error.to_string().contains("--tp-size=4"));
390	    }
391	
392	    #[test]
393	    fn ep8_rejects_tp4_tp_size() {
394	        let error = validate_argv(&["pegainfer", "--tp-size", "4"])
395	            .expect_err("GLM5.2 EP8 should reject --tp-size=4");
396	        assert!(error.to_string().contains("--tp-size=1"));
397	    }
398	
399	    #[test]
400	    fn rejects_unknown_moe_topo() {
401	        let error = validate_argv(&["pegainfer", "--moe-topo", "tp2"])
402	            .expect_err("GLM5.2 should reject an unknown topology string");
403	        assert!(
404	            error
405	                .to_string()
406	                .contains("ep4, ep8, ep16, ep32, ep64, or tp4")
407	        );
408	    }
409	
410	    #[test]
411	    fn accepts_ep4_default_dp4() {
412	        validate_argv(&["pegainfer", "--moe-topo", "ep4"])
413	            .expect("GLM5.2 EP4 should default to DP4 with --tp-size=1");
414	    }
415	
416	    #[test]
417	    fn ep4_rejects_non_dp4() {
418	        let error = validate_argv(&["pegainfer", "--moe-topo", "ep4", "--dp-size", "8"])
419	            .expect_err("GLM5.2 EP4 should reject explicit non-DP4");
420	        assert!(error.to_string().contains("--dp-size=4"));
421	    }
422	
423	    #[test]
424	    fn prefill_only_accepts_tp4_defaults() {
425	        validate_argv(&[
426	            "pegainfer",
427	            "--moe-topo",
428	            "tp4",
429	            "--tp-size",
430	            "4",
431	            "--glm52-prefill-only",
432	        ])
433	        .expect("TP4 prefill-only defaults should validate");
434	    }
435	
436	    #[test]
437	    fn prefill_only_rejects_decode_features() {
438	        for extra in [
439	            vec!["--no-prefix-cache"],
440	            vec!["--dflash-draft-model-path", "/tmp/dspark"],
441	            vec!["--dump-graph-png", "/tmp/decode.png"],
442	        ] {
443	            let mut argv = vec![
444	                "pegainfer",
445	                "--moe-topo",
446	                "tp4",
447	                "--tp-size",
448	                "4",
449	                "--glm52-prefill-only",
450	            ];
451	            argv.extend(extra);
452	            validate_argv(&argv).expect_err("prefill-only must reject decode-only features");
453	        }
454	    }
455	
456	    #[test]
457	    fn prefill_chunk_requires_mode_and_page_alignment() {
458	        let error = validate_argv(&["pegainfer", "--glm52-prefill-chunk-size", "16384"])
459	            .expect_err("an inert chunk size must be rejected");
460	        assert!(error.to_string().contains("requires --glm52-prefill-only"));
461	
462	        let error = validate_argv(&[
463	            "pegainfer",
464	            "--moe-topo",
465	            "tp4",
466	            "--tp-size",
467	            "4",
468	            "--glm52-prefill-only",
469	            "--glm52-prefill-chunk-size",
470	            "16001",
471	        ])
472	        .expect_err("unaligned chunk must be rejected");
473	        assert!(error.to_string().contains("positive multiple of 64"));
474	    }
475	
476	    #[test]
477	    fn serve_plan_counts_partial_fleet_ranks() {
478	        let (shared, matches, _provided) = parse_for_line(
479	            &MODEL_LINE,
480	            &[
481	                "pegainfer",
482	                "--moe-topo",
483	                "ep16",
484	                "--glm52-ranks",
485	                "4..8",
486	                "--glm52-rendezvous",
487	                "host:1",
488	            ],
489	        )
490	        .expect("partial-fleet flags should parse");
491	        let config = serde_json::json!({});
492	        let ctx = LaunchContext {
493	            model_path: std::path::Path::new("unused"),
494	            config: &config,
495	            shared: &shared,
496	            matches: &matches,
497	        };
498	        let plan = MODEL_LINE.serve_plan(&ctx).expect("serve plan");
499	        assert_eq!(plan.scheduler_partition_count, 4);
500	        assert!(!plan.prefill_only);
501	    }
502	}
