119	/// Parse a `--glm52-ranks` value (`start..end`, e.g. `4..8`) into the global
120	/// DP rank range a process hosts.
121	fn parse_rank_range(spec: &str) -> Result<Range<usize>> {
122	    let (start, end) = spec
123	        .split_once("..")
124	        .with_context(|| format!("rank range `{spec}` must be start..end (e.g. 4..8)"))?;
125	    let start: usize = start
126	        .parse()
127	        .with_context(|| format!("rank range `{spec}` has a non-numeric start"))?;
128	    let end: usize = end
129	        .parse()
130	        .with_context(|| format!("rank range `{spec}` has a non-numeric end"))?;
131	    ensure!(start < end, "rank range `{spec}` must satisfy start < end");
132	    Ok(start..end)
133	}
