197	/// Launch-time MoE sharding topology (the expert slab is repacked during
198	/// H2D load, so this is a boot choice — the two layouts never co-reside).
199	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, serde::Serialize, serde::Deserialize)]
200	pub enum Glm52MoeTopo {
201	    #[default]
202	    Ep8,
203	    /// Four-GPU expert-parallel layout (DP4/EP4, 64 whole routed experts per
204	    /// rank — the GB300 high-throughput target). Same DeepEP protocol as EP8
205	    /// with its own shim instantiation; routed experts use the SM100
206	    /// DeepGEMM masked grouped chain.
207	    Ep4,
208	    /// Cross-tray expert-parallel widths on GB300 NVL72 (4 GPUs per tray;
209	    /// every tray's process hosts its own ranks behind `--glm52-ranks`).
210	    /// Same DeepEP protocol with one
211	    /// shim instantiation per width; all run the SM100 DeepGEMM chain.
212	    Ep16,
213	    Ep32,
214	    Ep64,
215	    Tp4,
216	}
217	
218	impl Glm52MoeTopo {
219	    #[must_use]
220	    fn default_dp_size(self) -> usize {
221	        match self {
222	            Self::Tp4 => 1,
223	            _ => self.device_count(),
224	        }
225	    }
226	
227	    #[must_use]
228	    fn device_count(self) -> usize {
229	        match self {
230	            Self::Ep8 => GLM52_EP_RANKS,
231	            Self::Ep4 | Self::Tp4 => 4,
232	            Self::Ep16 => 16,
233	            Self::Ep32 => 32,
234	            Self::Ep64 => 64,
235	        }
236	    }
237	
238	    /// Number of independently scheduled request partitions. Tensor-
239	    /// replicated workers execute one mirrored partition in lock-step.
240	    #[must_use]
241	    fn logical_rank_count(self) -> usize {
242	        if self.uses_tensor_replicated_moe() {
243	            1
244	        } else {
245	            self.device_count()
246	        }
247	    }
248	
249	    /// The `--tp-size` this topology requires (server validation mirrors the
250	    /// launch-time ensure).
251	    #[must_use]
252	    fn expected_tp_size(self) -> usize {
253	        match self {
254	            Self::Tp4 => 4,
255	            _ => 1,
256	        }
257	    }
258	
259	    #[must_use]
260	    fn expected_ep_size(self) -> usize {
261	        match self {
262	            Self::Tp4 => 1,
263	            _ => self.device_count(),
264	        }
265	    }
266	
267	    #[must_use]
268	    fn uses_ep_expert_bundles(self) -> bool {
269	        !self.uses_tensor_replicated_moe()
270	    }
271	
272	    /// Whole routed experts per rank of an expert-bundle topology (EP8 → 32,
273	    /// EP4 → 64). Meaningless for the tensor-replicated topologies.
274	    #[must_use]
275	    fn ep_local_experts(self) -> usize {
276	        debug_assert!(self.uses_ep_expert_bundles());
277	        GLM52_ROUTED_EXPERTS / self.expected_ep_size()
278	    }
279	
280	    /// Whether this topology mirrors one logical rank across all workers
281	    /// (TP4) — the server needs it to size the frontend partition count
282	    /// for a hosted rank range.
283	    #[must_use]
284	    fn uses_tensor_replicated_moe(self) -> bool {
285	        matches!(self, Self::Tp4)
286	    }
287	}
