291	
292	    fn from_str(s: &str) -> Result<Self> {
293	        match s {
294	            "ep4" => Ok(Self::Ep4),
295	            "ep8" => Ok(Self::Ep8),
296	            "ep16" => Ok(Self::Ep16),
297	            "ep32" => Ok(Self::Ep32),
