717	/// The legacy `slots x cap` pool sizing — the cap-derivation NOMINAL (the
718	/// binary search finds the largest cap whose nominal-pool cost fits), and
719	/// the floor the budget fill starts from.
720	fn glm52_nominal_pool_blocks(max_model_len: usize) -> usize {
721	    glm52_pool_blocks(max_model_len, model::glm52_decode_slots())
722	}
723	
724	fn glm52_prefill_scratch_reservation(
725	    prefill_only: Option<Glm52PrefillOnlyOptions>,
726	) -> Result<usize> {
727	    let Some(prefill) = prefill_only else {
728	        return Ok(0);
729	    };
730	    prefill
731	        .chunk_size
732	        .checked_mul(GLM52_PREFILL_SCRATCH_BYTES_PER_TOKEN)
733	        .and_then(|bytes| bytes.checked_add(GLM52_PREFILL_FIXED_SCRATCH_BYTES))
734	        .context("GLM5.2 prefill scratch reservation overflow")
735	}
736	
737	/// Decide the per-request context cap from the post-weight-load VRAM budget.
738	/// Every slot's cache region is sized `max_model_len` tokens at build, so a
739	/// candidate cap's cost is exact arithmetic ([`glm52_cap_bytes`]) over the
740	/// fleet-minimum free bytes — kept free of CUDA so the policy is
741	/// unit-testable. Auto mode binary-searches the largest aligned cap that
742	/// fits; an explicit cap must be aligned and fit, or launch fails.
743	fn derive_max_model_len(
744	    requested: Option<usize>,
745	    min_free_vram_bytes: usize,
746	    drafter: &Glm52Drafter,
747	    prefill_scratch_bytes: usize,
748	    prefill_only: bool,
749	    moe_topo: Glm52MoeTopo,
750	) -> Result<Glm52ContextBudget> {
751	    let reserve_bytes = GLM52_VRAM_RESERVE_BYTES
752	        + if drafter.is_dspark() {
753	            GLM52_DSPARK_VRAM_RESERVE_BYTES
754	        } else {
755	            0
756	        }
757	        + prefill_scratch_bytes;
758	    let budget_bytes = min_free_vram_bytes.saturating_sub(reserve_bytes);
759	    let max_model_len = if let Some(requested) = requested {
760	        ensure!(
761	            requested >= GLM52_MIN_MODEL_LEN,
762	            "GLM5.2 --max-model-len {requested} is below the minimum {GLM52_MIN_MODEL_LEN}"
763	        );
764	        ensure!(
765	            requested <= GLM52_MAX_CONTEXT,
766	            "GLM5.2 --max-model-len {requested} exceeds the checkpoint's \
767	             max_position_embeddings {GLM52_MAX_CONTEXT}"
768	        );
769	        ensure!(
770	            requested.is_multiple_of(GLM52_MODEL_LEN_ALIGN),
771	            "GLM5.2 --max-model-len {requested} must be a multiple of {GLM52_MODEL_LEN_ALIGN} \
772	             (the FlashMLA page size); nearest valid values are {} and {}",
773	            requested / GLM52_MODEL_LEN_ALIGN * GLM52_MODEL_LEN_ALIGN,
774	            requested.next_multiple_of(GLM52_MODEL_LEN_ALIGN),
775	        );
776	        // The pool no longer multiplies the cap by the slot count (#818):
777	        // an explicit cap only has to fit the fixed arenas plus a pool that
778	        // can hold ONE max-length request — admission's lifetime reservation
779	        // guards each request, concurrency comes from whatever pool the
780	        // budget fill provides.
781	        let required = glm52_cap_bytes(
782	            requested,
783	            glm52_one_request_pool_blocks(requested),
784	            drafter,
785	            prefill_only,
786	            moe_topo,
787	        )?;
788	        // The graph reserve must survive the fill: without it a cap in the
789	        // band (budget - reserve, budget] passes here, the measured fill
790	        // floors at the one-request pool anyway, and FinishKv or the lazy
791	        // graph capture OOMs raw instead of failing at this door.
792	        ensure!(
793	            required + glm52_graph_reserve_bytes() <= budget_bytes,
794	            "GLM5.2 --max-model-len {requested} needs {} of cache per rank (fixed arenas + a \
795	             one-request pool + {} graph reserve) but only {} fits (min rank free VRAM {} - \
796	             reserve {}); lower it or free VRAM",
797	            ByteSize(required as u64),
798	            ByteSize(glm52_graph_reserve_bytes() as u64),
799	            ByteSize(budget_bytes as u64),
800	            ByteSize(min_free_vram_bytes as u64),
801	            ByteSize(reserve_bytes as u64),
802	        );
803	        requested
804	    } else {
805	        // Largest aligned cap whose exact cost fits the budget: the cost is
806	        // monotone in the cap, so binary search over the aligned candidates.
807	        let (mut lo, mut hi) = (0, GLM52_MAX_CONTEXT / GLM52_MODEL_LEN_ALIGN);
808	        while lo < hi {
809	            let mid = (lo + hi).div_ceil(2);
810	            if glm52_cap_bytes(
811	                mid * GLM52_MODEL_LEN_ALIGN,
812	                glm52_nominal_pool_blocks(mid * GLM52_MODEL_LEN_ALIGN),
813	                drafter,
814	                prefill_only,
815	                moe_topo,
816	            )? <= budget_bytes
817	            {
818	                lo = mid;
819	            } else {
820	                hi = mid - 1;
821	            }
822	        }
823	        let derived = lo * GLM52_MODEL_LEN_ALIGN;
824	        ensure!(
825	            derived >= GLM52_MIN_MODEL_LEN,
826	            "GLM5.2 free VRAM leaves a context cap of {derived} (< {GLM52_MIN_MODEL_LEN}): \
827	             budget {} (min rank free VRAM {} - reserve {})",
828	            ByteSize(budget_bytes as u64),
829	            ByteSize(min_free_vram_bytes as u64),
830	            ByteSize(reserve_bytes as u64),
831	        );
832	        derived
833	    };
834	    // Fill floor for the measured pool sizing (#818): the legacy nominal
835	    // (`slots x cap`) where the ledger says it still fits — identical
836	    // defaults — otherwise a pool holding one max-length request (the
837	    // explicit-big-cap shape the decoupling exists for). The ledger's job
838	    // ends here: the authoritative block count comes from the measured
839	    // two-phase fill between the workers' build phases.
840	    let nominal = glm52_nominal_pool_blocks(max_model_len);
841	    let floor_blocks = if glm52_cap_bytes(max_model_len, nominal, drafter, prefill_only, moe_topo)?
842	        <= budget_bytes
843	    {
844	        nominal
845	    } else {
846	        glm52_one_request_pool_blocks(max_model_len)
847	    };
848	    Ok(Glm52ContextBudget {
849	        max_model_len,
850	        floor_blocks,
851	        arena_bytes: glm52_cap_bytes(max_model_len, floor_blocks, drafter, prefill_only, moe_topo)?,
852	        reserve_bytes,
853	        budget_bytes,
854	    })
855	}
