1131	            rank,
1132	            submit_rx,
1133	            workers: engine_workers,
1134	            eos_token_ids: eos_token_ids.clone(),
1135	            drafter: drafter.clone(),
1136	            prefill_chunk_size: prefill_only.map(|prefill| prefill.chunk_size),
