1142	            no_prefix_cache,
1143	            moe_topo,
1144	            load_tx: load_txs[engine_index].clone(),
1145	            graph_dump_request: if engine_index == 0 {
1146	                graph_dump_request.take()
1147	            } else {
1148	                None
1149	            },
1150	            startup_tx,
1151	        };
