1492	/// One shared pegaflow host (one pinned pool) with each rank's arenas
1493	/// registered as its own instance under a single namespace — replicated
1494	/// non-expert weights make DP ranks' KV interchangeable, so any rank
1495	/// restores what any rank saved.
1496	/// The namespace folds the layout facts that make blocks interchange-safe
1497	/// (per-token packing, page size, layer count); pool capacity deliberately
1498	/// stays out (a block's bytes don't depend on it).
1499	/// Build the process-wide [`KvStore`]: every logical rank's pool, and — with
1500	/// offload configured — one shared [`PegaflowHost`] plus a per-rank pegaflow
1501	/// instance registration. All DP ranks share one namespace (replicated
1502	/// non-expert weights make their KV interchangeable), folding the layout
1503	/// facts that make blocks interchange-safe.
1504	fn build_kv_store(
1505	    opts: Option<&Glm52KvOffloadOptions>,
1506	    rank_arenas: Vec<Vec<ArenaSpec>>,
1507	    rank_mirrors: Vec<Vec<OffloadMirror>>,
1508	    native_mtp: bool,
1509	    device_ordinals: &[usize],
1510	    pools: &[Arc<BlockPool>],
1511	    ranks_start: usize,
1512	    runtime: &tokio::runtime::Handle,
1513	) -> Result<Arc<KvStore>> {
1514	    // The store's rank table is keyed by GLOBAL logical rank — the engines
1515	    // query it with `ranks.start + local_index` on a multi-process fleet.
1516	    let mut builder = KvStoreBuilder::new(runtime.clone());
1517	    let Some(opts) = opts else {
1518	        for (local, pool) in pools.iter().enumerate() {
1519	            builder = builder.rank(ranks_start + local, Arc::clone(pool));
1520	        }
1521	        return Ok(Arc::new(builder.build()));
1522	    };
1523	
1524	    // One page-granular arena per rank; the page layout constants ARE the
1525	    // block byte layout, so the registration only cross-checks that every
1526	    // rank's arena carries them.
1527	    ensure!(
1528	        rank_arenas.iter().all(|arenas| {
1529	            arenas.len() == 1
1530	                && arenas[0].name == "glm52.page"
1531	                && arenas[0].segment_bytes == crate::model::GLM52_KV_PAGE_CONTENT_BYTES
1532	                && arenas[0].block_stride_bytes == crate::model::GLM52_KV_PAGE_STRIDE
1533	        }),
1534	        "GLM5.2 KV offload expects one page-first arena per rank \
1535	         (segment {} B, stride {} B)",
1536	        crate::model::GLM52_KV_PAGE_CONTENT_BYTES,
1537	        crate::model::GLM52_KV_PAGE_STRIDE,
1538	    );
1539	    let mut host_builder = PegaflowHost::builder(opts.pinned_pool_bytes)
1540	        .use_hugepages(opts.use_hugepages)
1541	        .runtime_threads(2);
1542	    if let Some(p2p) = &opts.p2p {
1543	        host_builder = host_builder.p2p(P2pConfig {
1544	            metaserver_addr: p2p.metaserver_addr.clone(),
1545	            advertise_addr: p2p.advertise_addr.clone(),
1546	            rdma_nics: p2p.rdma_nics.clone(),
1547	        });
1548	    }
1549	    let host = host_builder
1550	        .build()
1551	        .map_err(|err| anyhow::anyhow!("GLM5.2 KV offload host: {err}"))?;
1552	    // The stride is the layout identity: one page carries every layer's MLA
1553	    // + index-K slices and the L78 MTP mirror slices (drafter or not), so
1554	    // agreeing on (layer count, token page, stride) is agreeing on every
1555	    // byte of a block's SHAPE. The mtp flag is the content half: a
1556	    // drafterless producer reserves the L78 slices but never writes them,
1557	    // and a native-MTP consumer restoring such a page would propose from
1558	    // zeros — the two configs must not see each other's blocks.
1559	    let namespace = format!(
1560	        "pegainfer-glm52-l{GLM52_LAYERS}-p{}-page{}-mtp{}",
1561	        pegainfer_kernels::ops::GLM52_FLASHMLA_SPARSE_PAGE_SIZE,
1562	        crate::model::GLM52_KV_PAGE_STRIDE,
1563	        usize::from(native_mtp),
1564	    );
1565	    ensure!(
1566	        rank_arenas.len() == pools.len() && device_ordinals.len() == pools.len(),
1567	        "GLM5.2 KV offload: {} arena sets, {} pools, {} devices must agree",
1568	        rank_arenas.len(),
1569	        pools.len(),
1570	        device_ordinals.len()
1571	    );
1572	    ensure!(
1573	        rank_mirrors.len() == pools.len(),
1574	        "GLM5.2 KV offload: {} mirror sets for {} pools",
1575	        rank_mirrors.len(),
1576	        pools.len()
1577	    );
1578	    let ranks = rank_arenas.len();
1579	    let arenas_per_rank = rank_arenas.first().map_or(0, Vec::len);
1580	    let mirrors_per_rank = rank_mirrors.first().map_or(0, Vec::len);
1581	    for (local, ((arenas, mirrors), &device_ordinal)) in rank_arenas
1582	        .into_iter()
1583	        .zip(rank_mirrors)
1584	        .zip(device_ordinals)
1585	        .enumerate()
1586	    {
1587	        let rank = ranks_start + local;
1588	        builder = builder
1589	            .rank_with_offload(
1590	                rank,
1591	                Arc::clone(&pools[local]),
1592	                &host,
1593	                OffloadRankSpec {
1594	                    instance_id: format!("glm52-rank{rank}"),
1595	                    namespace: namespace.clone(),
1596	                    device_id: device_ordinal as i32,
1597	                    arenas,
1598	                    page_first: false,
1599	                    mirrors,
1600	                },
1601	            )
1602	            .map_err(|err| {
1603	                anyhow::anyhow!("GLM5.2 KV offload rank {rank} registration: {err:#}")
1604	            })?;
1605	    }
1606	    log::info!(
1607	        "GLM5.2 KV offload up: {} pinned host pool (hugepages: {}), namespace {namespace}, \
1608	         {ranks} rank instances x {arenas_per_rank} arenas ({mirrors_per_rank} mirrors each)",
1609	        ByteSize(opts.pinned_pool_bytes as u64),
1610	        opts.use_hugepages,
1611	    );
1612	    Ok(Arc::new(builder.build()))
1613	}
