1615	/// The store's watcher/resolver runtime: the ambient tokio runtime when the
1616	/// loader runs under one (pegainfer-server's `spawn_blocking` keeps the
1617	/// context), else a small dedicated runtime living for the process.
1618	fn store_runtime_handle() -> tokio::runtime::Handle {
1619	    if let Ok(handle) = tokio::runtime::Handle::try_current() {
1620	        return handle;
1621	    }
1622	    static FALLBACK: std::sync::OnceLock<tokio::runtime::Runtime> = std::sync::OnceLock::new();
1623	    FALLBACK
1624	        .get_or_init(|| {
1625	            tokio::runtime::Builder::new_multi_thread()
1626	                .worker_threads(2)
1627	                .enable_all()
1628	                .build()
1629	                .expect("kv-store fallback runtime")
1630	        })
1631	        .handle()
1632	        .clone()
1633	}
