1635	fn validate_startup(
1636	    model_path: &Path,
1637	    options: &Glm52LoadOptions,
1638	    moe_topo: Glm52MoeTopo,
1639	    native_mtp: bool,
1640	) -> Result<StartupValidation> {
1641	    let config_path = model_path.join("config.json");
1642	    let content = std::fs::read_to_string(&config_path)
1643	        .map_err(|err| anyhow::anyhow!("read {}: {err}", config_path.display()))?;
1644	    let json: serde_json::Value = serde_json::from_str(&content)
1645	        .map_err(|err| anyhow::anyhow!("parse {}: {err}", config_path.display()))?;
1646	    probe_config_json(&json)?;
1647	
1648	    let expected_devices = moe_topo.device_count();
1649	    ensure!(
1650	        options.ranks.end <= expected_devices && options.ranks.start < options.ranks.end,
1651	        "GLM5.2 {moe_topo:?} load requires ranks within 0..{expected_devices}, got {}..{}",
1652	        options.ranks.start,
1653	        options.ranks.end
1654	    );
1655	    ensure!(
1656	        options.tp_size == moe_topo.expected_tp_size()
1657	            && options.dp_size == moe_topo.default_dp_size()
1658	            && options.ep_size == moe_topo.expected_ep_size(),
1659	        "GLM5.2 {moe_topo:?} requires TP{}/DP{}/EP{}, got TP{} DP{} EP{}",
1660	        moe_topo.expected_tp_size(),
1661	        moe_topo.default_dp_size(),
1662	        moe_topo.expected_ep_size(),
1663	        options.tp_size,
1664	        options.dp_size,
1665	        options.ep_size
1666	    );
1667	
1668	    let manifest = Glm52WeightManifest::from_model_dir(model_path)?;
1669	    let rank_bundles = manifest.all_rank_load_bundles(moe_topo, native_mtp)?;
1670	    let mut rank_tensor_counts = Vec::with_capacity(options.ranks.len());
1671	    let mut rank_expert_ranges = Vec::with_capacity(options.ranks.len());
1672	    for bundle in &rank_bundles[options.ranks.clone()] {
1673	        rank_tensor_counts.push(bundle.plan.tensor_count);
1674	        rank_expert_ranges.push(bundle.plan.expert_range.clone());
1675	    }
1676	
1677	    log::info!(
1678	        "GLM5.2 load-weight startup validated: model_path={}, fleet_ranks={}, hosted_ranks={:?}, logical_parallel=TP{} DP{} EP{}, rank_expert_ranges={:?}, rank_plan_tensors={:?}",
1679	        model_path.display(),
1680	        rank_bundles.len(),
1681	        options.ranks,
1682	        options.tp_size,
1683	        options.dp_size,
1684	        options.ep_size,
1685	        rank_expert_ranges,
1686	        rank_tensor_counts,
1687	    );
1688	
1689	    Ok(StartupValidation {
1690	        ranks: options.ranks.clone(),
1691	        rendezvous: options.rendezvous.clone(),
1692	        rank_bundles,
1693	        rank_tensor_counts,
1694	        rank_expert_ranges,
1695	    })
1696	}
