1698	fn load_rank_weights_to_gpu(
1699	    model_path: &Path,
1700	    startup: &StartupValidation,
1701	    moe_topo: Glm52MoeTopo,
1702	    weight_staging: bool,
1703	) -> Result<LoadedGlm52Runtime> {
1704	    let spawn_started = Instant::now();
1705	    log::info!(
1706	        "start spawn GLM5.2 rank workers: hosted_ranks={:?}",
1707	        startup.ranks,
1708	    );
1709	    let mut workers = Vec::with_capacity(startup.ranks.len());
1710	    for (device_ordinal, rank) in startup.ranks.clone().enumerate() {
1711	        let placement = Glm52RankPlacement {
1712	            rank,
1713	            device_ordinal,
1714	        };
1715	        workers.push(Glm52RankWorker::spawn(
1716	            placement,
1717	            startup.rank_bundles[rank].clone(),
1718	        )?);
1719	    }
1720	    log::info!(
1721	        "spawn GLM5.2 rank workers cost {:.2}s: ranks={}",
1722	        spawn_started.elapsed().as_secs_f64(),
1723	        workers.len()
1724	    );
1725	
1726	    let load_started = Instant::now();
1727	    log::info!(
1728	        "start load GLM5.2 rank weights: ranks={}, rank_expert_ranges={:?}",
1729	        workers.len(),
1730	        startup.rank_expert_ranges,
1731	    );
1732	    let load_results = workers
1733	        .iter()
1734	        .map(|worker| worker.load_weights_async(model_path, moe_topo, weight_staging))
1735	        .collect::<Result<Vec<_>>>()?;
1736	    let mut reports = Vec::with_capacity(load_results.len());
1737	    for (local_index, rx) in load_results.into_iter().enumerate() {
1738	        // `report.rank` is the global fleet rank; the enumerate index is only
1739	        // this process's worker slot, so recompute the rank from the hosted
1740	        // range before validating (matters when ranks.start != 0).
1741	        let rank = startup.ranks.start + local_index;
1742	        let report = rx
1743	            .recv()
1744	            .map_err(|_| anyhow::anyhow!("GLM5.2 rank {rank} worker dropped load response"))??;
1745	        ensure!(
1746	            report.rank == rank && report.loaded_to_gpu,
1747	            "GLM5.2 rank {rank} invalid weight-load report: {:?}",
1748	            report
1749	        );
1750	        reports.push(report);
1751	    }
1752	    let rank_tensor_counts = reports
1753	        .iter()
1754	        .map(|report| report.loaded_tensor_count)
1755	        .collect::<Vec<_>>();
1756	    let rank_bytes = reports
1757	        .iter()
1758	        .map(|report| report.loaded_total_bytes)
1759	        .collect::<Vec<_>>();
1760	    let rank_free_vram_bytes = reports
1761	        .iter()
1762	        .map(|report| report.free_vram_bytes)
1763	        .collect::<Vec<_>>();
1764	    log::info!(
1765	        "GLM5.2 rank weight load cost {:.2}s: ranks={}, tensors={:?}, resident_bytes={:?}",
1766	        load_started.elapsed().as_secs_f64(),
1767	        reports.len(),
1768	        rank_tensor_counts,
1769	        format_bytes(&rank_bytes),
1770	    );
1771	
1772	    Ok(LoadedGlm52Runtime {
1773	        workers,
1774	        report: GpuWeightLoadReport {
1775	            tensor_counts: rank_tensor_counts,
1776	            bytes: rank_bytes,
1777	            free_vram_bytes: rank_free_vram_bytes,
1778	        },
1779	    })
1780	}
